from pathlib import Path
import re,html
D=Path(__file__).resolve().parents[1]/'docs'
BASE='https://hqawasmeh.github.io/CreativeOS-Releases/'
def icon(name):return f'<span class="ui-icon fi-rr-{name}" aria-hidden="true"></span>'
ICON=icon('arrow-right')
ICON_MAP={'◫':'folder','♧':'users','▤':'document','▦':'receipt','◈':'apps','ϟ':'bolt','✧':'sparkles','↗':'arrow-up-right','→':'arrow-right','↑':'arrow-up','✓':'check','☑':'checkbox','◎':'eye'}
def interface_icons(markup):
 parts=re.split(r'(<[^>]+>)',markup)
 for i in range(0,len(parts),2):
  for symbol,name in ICON_MAP.items():parts[i]=parts[i].replace(symbol,icon(name))
 return ''.join(parts)
def btn(text,href='signup.html',secondary=False):
 if text in ['Get started','Get started with Qanteak']:return f'<a class="button primary start-button" href="{href}">Start for free</a>'
 return f'<a class="button {"secondary" if secondary else "primary"}" href="{href}">{text}{ICON}</a>'
def heading(k,t,p=''):return f'<div class="section-heading"><span class="eyebrow">{k}</span><h2>{t}</h2><p>{p}</p></div>'
def intro(k,t,p):return f'<section class="page-intro wrap"><span class="eyebrow">{k}</span><h1>{t}</h1><p>{p}</p></section>'
def cta():return '<section class="closing wrap"><span class="eyebrow">A LITTLE LESS CHAOS. A LOT MORE CLARITY.</span><h2>Make room for<br>your best work.</h2><p>One place for the details. More space for the bigger picture.</p>'+btn('Create your account')+btn('Explore the product','product.html',True)+'</section>'
def nav(active):
 links=''.join(f'<a {"aria-current=\"page\"" if active==slug else ""} href="{slug}.html">{label}</a>' for slug,label in [('product','Product'),('solutions','Solutions'),('ai','Qanteak AI'),('pricing','Pricing'),('resources','Resources')])
 return f'<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="nav wrap"><a class="brand" href="index.html" aria-label="Qanteak OS home"><img src="assets/qanteak-logo.png" alt="Qanteak OS" width="145" height="45"></a><nav id="navigation" aria-label="Main navigation">{links}<a class="mobile-login" href="login.html">Log in</a></nav><div class="nav-actions"><a href="login.html" class="login-link">Log in</a>{btn("Get started")}</div><button class="menu-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="navigation"><span class="ui-icon fi-rr-menu-burger" aria-hidden="true"></span></button></div></header>'
