 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8faff"><title>{title} — Qanteak OS</title><meta name="description" content="{html.escape(desc or 'Your work. Your business. One workspace. Connect projects, clients, documents and business operations with Qanteak OS.',quote=True)}"><link rel="canonical" href="{BASE}{'' if slug=='index' else slug+'.html'}"><meta property="og:title" content="{html.escape(title)} — Qanteak OS"><meta property="og:type" content="website"><link rel="icon" href="assets/qanteak-hub-symbol.svg" type="image/svg+xml"><link rel="preload" href="assets/fonts/av-estiana.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="icons.css?v=20260919"><link rel="stylesheet" href="site.css?v=20260919-icons">{scripts}</head><body>{nav(slug)}<main id="main">{body}</main>{footer()}<div id="toast" role="status" aria-live="polite"></div></body></html>'''
 (D/f'{slug}.html').write_text(interface_icons(out))

