page('about','Built around the way you work',intro('THE IDEA BEHIND QANTEAK','Good work deserves<br><em>a better home.</em>','Projects in one app. Clients in another. Feedback in a message thread. The work connects—but the tools often do not.')+'''<section class="about-story wrap"><h2>It starts with<br>the connections.</h2><div><p>Qanteak is built around a simple idea: the project, the client, the brief, the files and the invoice should understand that they belong to the same work.</p><p>That shared context makes everyday work easier to follow. It also creates a more useful foundation for automation and AI, because the important relationships are already there.</p><p>Our ambition is to build an operating system for your work. A flexible space to plan, deliver, learn and run a business with a clearer view of the whole.</p></div></section><section class="wrap manifesto"><span class="eyebrow">OUR GUIDING IDEA</span><h2>Your work.<br>Your business.<br><em>One workspace.</em></h2></section>'''+cta())

page('download','Your workspace, on your desktop',intro('QANTEAK FOR WINDOWS','A home for your work.<br><em>Right on your desktop.</em>','Download the current Qanteak OS preview release and bring your connected workspace to Windows.')+'''<section class="download-card wrap"><img src="assets/qanteak-hub-symbol.svg" alt="Qanteak symbol"><h2>Qanteak OS</h2><p>Windows desktop · Release candidate</p>'''+btn('Download for Windows','https://github.com/Hqawasmeh/CreativeOS-Releases/releases/download/v1.0.0-rc.9.21/QanteakOS-Setup-1.0.0-rc.9.21.exe')+'''<p class="small" id="release-info">RC9 V0.21 · Preview software</p><a class="text-link" href="https://github.com/Hqawasmeh/CreativeOS-Releases/releases">Release notes ↗</a></section><section class="section wrap"><div class="feature-three"><article class="feature-link"><span class="eyebrow">01</span><h3>Download & install.</h3><p>Download the Windows installer. This release candidate is intended for evaluation; Windows may show an unsigned-app notice.</p></article><article class="feature-link"><span class="eyebrow">02</span><h3>Sign in.</h3><p>Use your Qanteak account to connect to the configured cloud workspace. Paid access follows your subscription.</p></article><article class="feature-link"><span class="eyebrow">03</span><h3>Make it yours.</h3><p>Start with a client and a project. Add the tasks, documents and details that bring it to life.</p></article></div><p class="center muted">macOS, iOS and Android downloads are not available yet.</p></section>''')

# Preserve the actual policy text while bringing the existing legal pages into the design system.
for slug,title in [('privacy','Privacy Policy'),('terms','Terms of Service'),('refund','Refund Policy'),('security','Security')]:
 old=(D/f'{slug}.html').read_text();match=re.search(r'<main[^>]*>(.*?)</main>',old,re.S)
 content=match.group(1) if match else ''
 content=re.sub(r'^<article class="legal-page wrap">(.*)</article>$',r'\1',content,flags=re.S)
 content=re.sub(r'<a class="back".*?</a>','',content,flags=re.S)
 content=re.sub(r'<div class="links">.*?</div>','',content,flags=re.S)
 page(slug,title,'<article class="legal-page wrap">'+content+'</article>')

# Contact opens an email draft rather than claiming to submit an unconnected form.
page('contact','Let’s talk about your workspace',intro('GET IN TOUCH','Good conversations.<br><em>Better workflows.</em>','Questions about Qanteak, a team rollout, or something that needs attention? Tell us what you have in mind.')+'''<section class="contact-layout wrap"><div><h2>How can we help?</h2><p>Share a little context so we can understand your work and your question.</p><div class="contact-note"><h3>Product questions</h3><p>Plans, capabilities and getting started.</p><h3>Technical support</h3><p>Include your app version and the steps that led to the issue.</p></div></div><form id="contact-form" class="form-card"><label>Your name<input name="name" required autocomplete="name" maxlength="100"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label><label>What is this about?<select name="topic"><option>Product question</option><option>Team enquiry</option><option>Technical support</option><option>Feedback</option></select></label><label>Your message<textarea name="message" required rows="5" maxlength="5000" placeholder="Tell us a little about your work…"></textarea></label><button class="button primary" type="submit">Prepare email ↗</button><p class="small muted">Opens a draft in your email app. Your message is sent only when you send that email.</p><p class="form-message" role="status"></p></form></section>''')

for slug,mode,title,desc in [('signup','signup','Your next chapter<br>starts here.','Create your Qanteak account and give your work a home.'),('login','login','Welcome back.','Sign in to your Qanteak account.'),('reset-password','reset','A fresh start.','Enter your email to request a password reset link.')]:
 fields=('<label>Full name<input name="name" required autocomplete="name" maxlength="100" placeholder="Your name"></label><label>Workspace name<input name="workspace" required maxlength="100" placeholder="Your studio or company"></label>' if mode=='signup' else '')+'<label>Email address<input name="email" type="email" required autocomplete="email" placeholder="you@company.com"></label>'
 if mode!='reset':fields+='<label>Password<div class="password-field"><input name="password" type="password" required minlength="8" autocomplete="'+('new-password' if mode=='signup' else 'current-password')+'" placeholder="At least 8 characters"><button type="button" class="show-password" aria-label="Show password">Show</button></div></label>'
 if mode=='signup':fields+='<label class="checkbox-label"><input type="checkbox" name="terms" required><span>I agree to the <a href="terms.html">Terms</a> and <a href="privacy.html">Privacy Policy</a>.</span></label>'
 fields+=f'<button type="submit" class="button primary">{ "Create account" if mode=="signup" else "Log in" if mode=="login" else "Send reset link"} {ICON}</button><p class="form-message" role="status" aria-live="polite"></p>'
 if mode in ('signup','login'):fields+='<div class="confirmation-help"><p class="small">Missing your confirmation email? Check spam or request another link using the email above.</p><button type="button" id="resend-confirmation" class="button secondary">Resend confirmation email</button><p id="resend-message" class="form-message" role="status" aria-live="polite"></p></div>'
 if mode=='signup':fields+='<p class="small center">Already have an account? <a href="login.html">Log in</a></p>'
 elif mode=='login':fields+='<div class="form-links"><a href="reset-password.html">Forgot password?</a><a href="signup.html">Create account</a></div>'
 else:fields+='<a href="login.html">Back to log in →</a>'
 page(slug,'Create your account' if mode=='signup' else 'Log in' if mode=='login' else 'Reset your password',f'<section class="auth-layout wrap"><div class="auth-story"><span class="eyebrow">YOUR WORK. YOUR BUSINESS. ONE WORKSPACE.</span><h1>{title}</h1><p>{desc}</p><div class="auth-software"><img src="assets/qanteak-home-v021.png" width="1904" height="1005" alt="Your projects, calendar and business together in Qanteak OS" loading="lazy"></div></div><div class="auth-form-wrap"><form id="auth-form" data-mode="{mode}" class="form-card"><h2>{"Create your account" if mode=="signup" else "Log in" if mode=="login" else "Reset password"}</h2><p id="selected-plan" class="small muted"></p>{fields}</form></div></section>',auth=True)
page('account','Your Qanteak account','''<section class="page-intro wrap"><span class="eyebrow">YOUR QANTEAK ACCOUNT</span><h1>A home for your work.</h1><p id="account-status" role="status">Checking your session…</p></section><section class="wrap account-content" id="account-content" hidden><div class="account-heading"><div><h2 id="account-name">Your account</h2><p id="account-email"></p></div><button id="sign-out" class="button secondary">Sign out</button></div><div class="info-grid"><article><span class="eyebrow">WORKSPACES</span><h3>Your connected spaces.</h3><div id="workspace-list">Loading workspaces…</div></article><article><span class="eyebrow">PLAN & ACCESS</span><h3 id="subscription-plan">Loading subscription…</h3><p id="subscription-description"></p><a href="pricing.html" class="text-link">Explore plans →</a></article></div><div class="notice"><h3>Your full workspace is in the desktop app.</h3><p>Open Qanteak on Windows and sign in with this account to access your work.</p>'''+btn('Get the Windows app','download.html')+'''</div></section><section id="recovery-section" class="wrap narrow" hidden><form id="recovery-form" class="form-card"><h2>Set a new password</h2><label>New password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirm" minlength="8" required autocomplete="new-password"></label><button class="button primary">Save password</button><p class="form-message" role="status"></p></form></section>''',auth=True)
page('404','Page not found',intro('404 / A SMALL DETOUR','This page has<br>left the workspace.','The link may have changed. Let’s get you back to somewhere useful.')+'<div class="center section">'+btn('Back to Qanteak','index.html')+btn('Browse resources','resources.html',True)+'</div>')
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}{"" if p=="index" else p+".html"}</loc></url>' for p in ['index','product','solutions','ai','pricing','resources','about','download','contact','privacy','terms','refund','security'])+'</urlset>')
print('Generated complete website pages.')
